 void CreateFirst(){App.Host.Config.Bars.Add(new(){Name="My workspace",Monitors=[Monitor.All().FirstOrDefault(m=>m.Primary)?.Id??Monitor.All()[0].Id],Mode=BarMode.Launcher});}
