  var appearance=Page("Appearance");var preview=new Border{Padding=new Thickness(15),Margin=new Thickness(0,0,0,15)};var icons=new StackPanel{Orientation=Orientation.Horizontal};preview.Child=icons;appearance.Children.Add(preview);
