 FrameworkElement GlobalPage(){var p=new StackPanel();p.Children.Add(Ui.Text("Windows integration",24,true));Ui.Check(p,"Start DockForge when I sign in",App.Host.Config.StartAtSignIn,v=>App.Host.Config.StartAtSignIn=v);Ui.Check(p,"Confirm before closing all windows of an app",App.Host.Config.ConfirmCloseAll,v=>App.Host.Config.ConfirmCloseAll=v);p.Children.Add(Ui.Text("Hide the Windows taskbar on selected displays",16,true));p.Children.Add(Ui.Text("The original taskbars are restored when DockForge exits. Apply activates your selection.",13));var monitorPanel=new StackPanel();void Render(){monitorPanel.Children.Clear();foreach(var m in Monitor.All())Ui.Check(monitorPanel,m.Name,App.Host.Config.HiddenTaskbarMonitors.Contains(m.Id),v=>{if(v&&!App.Host.Config.HiddenTaskbarMonitors.Contains(m.Id))App.Host.Config.HiddenTaskbarMonitors.Add(m.Id);if(!v)App.Host.Config.HiddenTaskbarMonitors.Remove(m.Id);});}Render();p.Children.Add(monitorPanel);var row=new WrapPanel();row.Children.Add(Ui.Action("Keep all visible",()=>{App.Host.Config.HiddenTaskbarMonitors.Clear();Render();}));row.Children.Add(Ui.Action("Hide on secondary displays",()=>{App.Host.Config.HiddenTaskbarMonitors=Monitor.All().Where(m=>!m.Primary).Select(m=>m.Id).ToList();Render();}));row.Children.Add(Ui.Action("Hide on all displays",()=>{App.Host.Config.HiddenTaskbarMonitors=Monitor.All().Select(m=>m.Id).ToList();Render();}));p.Children.Add(row);p.Children.Add(Ui.Text("High contrast and Windows theme changes are followed automatically. DockForge does not collect usage data or send crash reports.",13));if(App.Host.Sandbox)p.Children.Add(Ui.Text("Preview session: sign-in and Windows taskbar changes are disabled.",14,true));return Scroll(p);}
 FrameworkElement DataPage(){var p=new StackPanel();p.Children.Add(Ui.Text("Keep your workspace",24,true));var row=new WrapPanel();row.Children.Add(Ui.Action("Export setup",()=>{var d=new Microsoft.Win32.SaveFileDialog{Filter="DockForge settings|*.json",FileName="DockForge-settings.json"};if(d.ShowDialog()==true)File.WriteAllText(d.FileName,JsonSerializer.Serialize(App.Host.Config,Settings.Json));}));row.Children.Add(Ui.Action("Import setup",()=>{var d=new Microsoft.Win32.OpenFileDialog{Filter="DockForge settings|*.json"};if(d.ShowDialog()==true)LoadSettings(d.FileName);}));row.Children.Add(Ui.Action("Restore backup",()=>{var d=new Microsoft.Win32.OpenFileDialog{Filter="DockForge backups|*.json",InitialDirectory=Path.Combine(App.Host.Store.Root,"Backups")};if(d.ShowDialog()==true)LoadSettings(d.FileName);}));row.Children.Add(Ui.Action("Export diagnostics",()=>{var d=new Microsoft.Win32.SaveFileDialog{Filter="Text log|*.txt",FileName="DockForge-diagnostics.txt"};if(d.ShowDialog()==true){string log=Path.Combine(Log.Root,"diagnostics.log");File.WriteAllText(d.FileName,File.Exists(log)?File.ReadAllText(log):"No diagnostic errors recorded.");}}));p.Children.Add(row);p.Children.Add(Ui.Text("Imports are validated before replacing settings. The previous setup is backed up locally; the newest eight backups are retained.",13));p.Children.Add(Ui.Text("Updates",22,true));Ui.Check(p,"Check GitHub Releases at startup",App.Host.Config.CheckUpdates,v=>App.Host.Config.CheckUpdates=v);Ui.Check(p,"Include development previews",App.Host.Config.IncludePreviewUpdates,v=>App.Host.Config.IncludePreviewUpdates=v);p.Children.Add(Ui.Text("Official update source: "+UpdateFeed.Repository,13));p.Children.Add(Ui.Action("Check now",async()=>await UpdateService.Check(true)));p.Children.Add(Ui.Text($"Version {UpdateService.DisplayVersion} · MIT license\nUpdates come from the official DockForge GitHub repository. Downloads require your confirmation; updates never install automatically.",13));return Scroll(p);}
 void LoadSettings(string path){try{var imported=SettingsStore.Read(path);App.Host.Store.Backup();App.Host.Config=imported;App.Host.RebuildBars();RefreshList();MessageBox.Show("Setup loaded. Review your bars, then Apply to save. Cancel restores the previous setup.","Import complete");}catch(Exception e){MessageBox.Show(e.Message,"Could not import settings");}}
